import csv
import io
import json


_FIELDS = ("id", "name")


def _normalize_rows(rows):
    for row in rows:
        yield {
            key: "" if row.get(key) is None else str(row[key])
            for key in _FIELDS
        }


def export_rows(rows, format):
    if format not in ("csv", "json"):
        raise ValueError("unsupported format")

    clean = _normalize_rows(rows)
    if format == "json":
        return json.dumps(list(clean), ensure_ascii=False, separators=(",", ":"))

    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    writer.writerows([row[key] for key in _FIELDS] for row in clean)
    return buffer.getvalue()

